INSERT INTO `paragraph_revision__field_description` VALUES ('stat_item',0,9,9,'en',0,'Developers and teams use LaunchPad daily','basic_html'),('stat_item',0,10,10,'en',0,'Enterprise-grade reliability','basic_html'),('stat_item',0,11,11,'en',0,'From over 2,000 reviews','basic_html'),('stat_item',0,12,12,'en',0,'Connect with your favorite tools','basic_html'),('card',0,14,14,'en',0,'Optimized for speed with instant page loads and real-time updates. Build experiences your users will love.','basic_html'),('card',0,15,15,'en',0,'SOC2 compliant with end-to-end encryption. Your data is protected with industry-leading security measures.','basic_html'),('card',0,16,16,'en',0,'Pre-built, customizable components that work together seamlessly. Mix and match to create your perfect stack.','basic_html'),('feature_item',0,18,18,'en',0,'Use our intuitive API and components to build your product quickly','basic_html'),('feature_item',0,19,19,'en',0,'Every branch gets a preview deployment for easy collaboration','basic_html'),('feature_item',0,20,20,'en',0,'One-click deployments with automatic scaling and optimization','basic_html'),('feature_item',0,22,22,'en',0,'PostgreSQL, MySQL, MongoDB, and more with automatic backups','basic_html'),('feature_item',0,23,23,'en',0,'Deploy to AWS, GCP, Azure, or our managed infrastructure','basic_html'),('feature_item',0,24,24,'en',0,'Built-in support for OAuth, SAML, and custom authentication','basic_html'),('pricing_tier',0,26,26,'en',0,'Perfect for side projects and learning','basic_html'),('pricing_tier',0,27,27,'en',0,'For professionals and growing teams','basic_html'),('pricing_tier',0,28,28,'en',0,'For large teams with custom needs','basic_html'),('card',0,42,42,'en',0,'CEO & Co-founder. Previously engineering lead at Stripe.','basic_html'),('card',0,43,43,'en',0,'CTO & Co-founder. Former senior engineer at Google Cloud.','basic_html'),('card',0,44,44,'en',0,'Head of Design. Led design teams at Figma and Notion.','basic_html'),('card',0,45,45,'en',0,'Head of Engineering. Built infrastructure at Netflix.','basic_html'),('card',0,48,48,'en',0,'Build on a modern, extensible platform with built-in CI/CD, auto-scaling, and infrastructure-as-code. Ship with confidence.','basic_html'),('card',0,49,49,'en',0,'Moving from another platform? Our migration specialists handle the transition — zero downtime, full data integrity guaranteed.','basic_html'),('card',0,50,50,'en',0,'Priority access to our engineering team. Dedicated Slack channel, 1-hour response SLA, and quarterly architecture reviews.','basic_html'),('card',0,51,51,'en',0,'Hands-on training for your team — from onboarding workshops to advanced performance optimization masterclasses.','basic_html'),('feature_item',0,53,53,'en',0,'Most teams are up and running in under a week with our guided setup process.','basic_html'),('feature_item',0,54,54,'en',0,'Real-time dashboards showing uptime, performance, and usage across all your projects.','basic_html'),('feature_item',0,55,55,'en',0,'SOC2, GDPR, and HIPAA compliance built in. Audit logs and access controls included.','basic_html');
